window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-c284d7b029c47722"]={"versions": [{"id": "FIG-c284d7b029c47722", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des AUTOSAR-ECU-Configuration-Metamodells (ECUC). Dargestellt ist die Konfigurationsstruktur des Containers <code>EcuMDefaultShutdownTarget</code> innerhalb des BSW-Moduls <code>EcuM</code> (ECU State Manager, Variante Fixed) mit seinen Parametern, Literaldefinitionen und Zielreferenzen auf Modi aus <code>EcuMFlex</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Container:</strong></li>\n<li><code>EcuMDefaultShutdownTarget</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 1..1): Konfigurationscontainer für das Standard-Herunterfahrziel.</li>\n<li><code>EcuMSleepMode</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 1..*): Zielcontainer für konfigurierte Schlafmodi.</li>\n<li><code>EcuMResetMode</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 1..*, Paketursprung <code>(from EcuMFlex)</code>): Zielcontainer für konfigurierte Resetmodi.</li>\n<li><strong>Parameter & Literale:</strong></li>\n<li><code>EcuMDefaultState</code> (<code>EcucEnumerationParamDef</code> via Aggregation <code>+parameter</code>): Enumerationsparameter für den Standard-Zielzustand. Aggregiert via <code>+literal</code> drei Ausprägungen (<code>EcucEnumerationLiteralDef</code>):</li>\n<li><code>EcuMStateSleep</code></li>\n<li><code>EcuMStateOff</code></li>\n<li><code>EcuMStateReset</code></li>\n<li><strong>Referenzen:</strong></li>\n<li><code>EcuMDefaultSleepModeRef</code> (<code>EcucSymbolicNameReferenceDef</code>, Multiplizität 0..1 via <code>+reference</code>): Symbolische Referenz mit Ziel <code>+destination</code> auf <code>EcuMSleepMode</code>.</li>\n<li><code>EcuMDefaultResetModeRef</code> (<code>EcucSymbolicNameReferenceDef</code>, Multiplizität 0..1 via <code>+reference</code>): Symbolische Referenz mit Ziel <code>+destination</code> auf <code>EcuMResetMode</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Konfigurationsmetamodell ohne dynamische Laufzeitsequenzen. Definiert die statische Vorgabe, mit welchem Standardzustand (<code>EcuMDefaultState</code>) und ggf. welchem konkreten Modus (<code>EcuMDefaultSleepModeRef</code> bzw. <code>EcuMDefaultResetModeRef</code>) das Steuergerät bei Fehlen abweichender Laufzeitanforderungen heruntergefahren oder in den Ruhezustand versetzt wird.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorgabe für Konfigurationswerkzeuge (BSW-Generatoren) und den EcuM-BSW-Stack:</p>\n<ul class=\"fig-list\">\n<li>Der Container <code>EcuMDefaultShutdownTarget</code> muss genau einmal instanziiert werden (Multiplizität 1..1).</li>\n<li>Wird als Standardzustand Sleep oder Reset gewählt, erfordert die Spezifikation die optionale Auflösung der symbolischen Referenz (<code>0..1</code>) auf mindestens einen existierenden Schlafmodus (<code>EcuMSleepMode</code>, 1..<em>) bzw. Resetmodus (<code>EcuMResetMode</code>, 1..</em>).</li>\n<li>Für den Zustand Off ist keine zusätzliche Modusreferenz vorgesehen.</li>\n</ul>"}, {"id": "FIG-68aaa5d915b806e7", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des AUTOSAR-ECU-Configuration-Metamodells (ECUC). Dargestellt ist die Konfigurationsstruktur des Containers <code>EcuMDefaultShutdownTarget</code> innerhalb des BSW-Moduls <code>EcuM</code> (ECU State Manager, Variante Fixed) mit seinen Parametern, Literaldefinitionen und Zielreferenzen auf Modi aus <code>EcuMFlex</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Container:</strong></li>\n<li><code>EcuMDefaultShutdownTarget</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 1..1): Konfigurationscontainer für das Standard-Herunterfahrziel.</li>\n<li><code>EcuMSleepMode</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 1..*): Zielcontainer für konfigurierte Schlafmodi.</li>\n<li><code>EcuMResetMode</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 1..*, Paketursprung <code>(from EcuMFlex)</code>): Zielcontainer für konfigurierte Resetmodi.</li>\n<li><strong>Parameter & Literale:</strong></li>\n<li><code>EcuMDefaultState</code> (<code>EcucEnumerationParamDef</code> via Aggregation <code>+parameter</code>): Enumerationsparameter für den Standard-Zielzustand. Aggregiert via <code>+literal</code> drei Ausprägungen (<code>EcucEnumerationLiteralDef</code>):</li>\n<li><code>EcuMStateSleep</code></li>\n<li><code>EcuMStateOff</code></li>\n<li><code>EcuMStateReset</code></li>\n<li><strong>Referenzen:</strong></li>\n<li><code>EcuMDefaultSleepModeRef</code> (<code>EcucSymbolicNameReferenceDef</code>, Multiplizität 0..1 via <code>+reference</code>): Symbolische Referenz mit Ziel <code>+destination</code> auf <code>EcuMSleepMode</code>.</li>\n<li><code>EcuMDefaultResetModeRef</code> (<code>EcucSymbolicNameReferenceDef</code>, Multiplizität 0..1 via <code>+reference</code>): Symbolische Referenz mit Ziel <code>+destination</code> auf <code>EcuMResetMode</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Konfigurationsmetamodell ohne dynamische Laufzeitsequenzen. Definiert die statische Vorgabe, mit welchem Standardzustand (<code>EcuMDefaultState</code>) und ggf. welchem konkreten Modus (<code>EcuMDefaultSleepModeRef</code> bzw. <code>EcuMDefaultResetModeRef</code>) das Steuergerät bei Fehlen abweichender Laufzeitanforderungen heruntergefahren oder in den Ruhezustand versetzt wird.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorgabe für Konfigurationswerkzeuge (BSW-Generatoren) und den EcuM-BSW-Stack:</p>\n<ul class=\"fig-list\">\n<li>Der Container <code>EcuMDefaultShutdownTarget</code> muss genau einmal instanziiert werden (Multiplizität 1..1).</li>\n<li>Wird als Standardzustand Sleep oder Reset gewählt, erfordert die Spezifikation die optionale Auflösung der symbolischen Referenz (<code>0..1</code>) auf mindestens einen existierenden Schlafmodus (<code>EcuMSleepMode</code>, 1..<em>) bzw. Resetmodus (<code>EcuMResetMode</code>, 1..</em>).</li>\n<li>Für den Zustand Off ist keine zusätzliche Modusreferenz vorgesehen.</li>\n</ul>"}, {"id": "FIG-e47f70a8847c89f8", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des AUTOSAR-ECU-Configuration-Metamodells (ECUC). Dargestellt ist die Konfigurationsstruktur des Containers <code>EcuMDefaultShutdownTarget</code> innerhalb des BSW-Moduls <code>EcuM</code> (ECU State Manager, Variante Fixed) mit seinen Parametern, Literaldefinitionen und Zielreferenzen auf Modi aus <code>EcuMFlex</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Container:</strong></li>\n<li><code>EcuMDefaultShutdownTarget</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 1..1): Konfigurationscontainer für das Standard-Herunterfahrziel.</li>\n<li><code>EcuMSleepMode</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 1..*): Zielcontainer für konfigurierte Schlafmodi.</li>\n<li><code>EcuMResetMode</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 1..*, Paketursprung <code>(from EcuMFlex)</code>): Zielcontainer für konfigurierte Resetmodi.</li>\n<li><strong>Parameter & Literale:</strong></li>\n<li><code>EcuMDefaultState</code> (<code>EcucEnumerationParamDef</code> via Aggregation <code>+parameter</code>): Enumerationsparameter für den Standard-Zielzustand. Aggregiert via <code>+literal</code> drei Ausprägungen (<code>EcucEnumerationLiteralDef</code>):</li>\n<li><code>EcuMStateSleep</code></li>\n<li><code>EcuMStateOff</code></li>\n<li><code>EcuMStateReset</code></li>\n<li><strong>Referenzen:</strong></li>\n<li><code>EcuMDefaultSleepModeRef</code> (<code>EcucSymbolicNameReferenceDef</code>, Multiplizität 0..1 via <code>+reference</code>): Symbolische Referenz mit Ziel <code>+destination</code> auf <code>EcuMSleepMode</code>.</li>\n<li><code>EcuMDefaultResetModeRef</code> (<code>EcucSymbolicNameReferenceDef</code>, Multiplizität 0..1 via <code>+reference</code>): Symbolische Referenz mit Ziel <code>+destination</code> auf <code>EcuMResetMode</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Konfigurationsmetamodell ohne dynamische Laufzeitsequenzen. Definiert die statische Vorgabe, mit welchem Standardzustand (<code>EcuMDefaultState</code>) und ggf. welchem konkreten Modus (<code>EcuMDefaultSleepModeRef</code> bzw. <code>EcuMDefaultResetModeRef</code>) das Steuergerät bei Fehlen abweichender Laufzeitanforderungen heruntergefahren oder in den Ruhezustand versetzt wird.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorgabe für Konfigurationswerkzeuge (BSW-Generatoren) und den EcuM-BSW-Stack:</p>\n<ul class=\"fig-list\">\n<li>Der Container <code>EcuMDefaultShutdownTarget</code> muss genau einmal instanziiert werden (Multiplizität 1..1).</li>\n<li>Wird als Standardzustand Sleep oder Reset gewählt, erfordert die Spezifikation die optionale Auflösung der symbolischen Referenz (<code>0..1</code>) auf mindestens einen existierenden Schlafmodus (<code>EcuMSleepMode</code>, 1..<em>) bzw. Resetmodus (<code>EcuMResetMode</code>, 1..</em>).</li>\n<li>Für den Zustand Off ist keine zusätzliche Modusreferenz vorgesehen.</li>\n</ul>"}, {"id": "FIG-20a9044bd53ef151", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des AUTOSAR-ECU-Configuration-Metamodells (ECUC). Dargestellt ist die Konfigurationsstruktur des Containers <code>EcuMDefaultShutdownTarget</code> innerhalb des BSW-Moduls <code>EcuM</code> (ECU State Manager, Variante Fixed) mit seinen Parametern, Literaldefinitionen und Zielreferenzen auf Modi aus <code>EcuMFlex</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Container:</strong></li>\n<li><code>EcuMDefaultShutdownTarget</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 1..1): Konfigurationscontainer für das Standard-Herunterfahrziel.</li>\n<li><code>EcuMSleepMode</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 1..256): Zielcontainer für konfigurierte Schlafmodi.</li>\n<li><code>EcuMResetMode</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 1..256, Paketursprung <code>(from EcuMFlex)</code>): Zielcontainer für konfigurierte Resetmodi.</li>\n<li><strong>Parameter & Literale:</strong></li>\n<li><code>EcuMDefaultShutdownTarget</code> (<code>EcucEnumerationParamDef</code> via Aggregation <code>+parameter</code>): Enumerationsparameter für das Standard-Herunterfahrziel. Aggregiert via <code>+literal</code> drei Ausprägungen (<code>EcucEnumerationLiteralDef</code>):</li>\n<li><code>EcuMShutdownTargetSleep</code></li>\n<li><code>EcuMShutdownTargetOff</code></li>\n<li><code>EcuMShutdownTargetReset</code></li>\n<li><strong>Referenzen:</strong></li>\n<li><code>EcuMDefaultSleepModeRef</code> (<code>EcucSymbolicNameReferenceDef</code>, Multiplizität 0..1 via <code>+reference</code>): Symbolische Referenz mit Ziel <code>+destination</code> auf <code>EcuMSleepMode</code>.</li>\n<li><code>EcuMDefaultResetModeRef</code> (<code>EcucSymbolicNameReferenceDef</code>, Multiplizität 0..1 via <code>+reference</code>): Symbolische Referenz mit Ziel <code>+destination</code> auf <code>EcuMResetMode</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Konfigurationsmetamodell ohne dynamische Laufzeitsequenzen. Definiert die statische Vorgabe, mit welchem Standardzustand (<code>EcuMDefaultState</code>) und ggf. welchem konkreten Modus (<code>EcuMDefaultSleepModeRef</code> bzw. <code>EcuMDefaultResetModeRef</code>) das Steuergerät bei Fehlen abweichender Laufzeitanforderungen heruntergefahren oder in den Ruhezustand versetzt wird.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorgabe für Konfigurationswerkzeuge (BSW-Generatoren) und den EcuM-BSW-Stack:</p>\n<ul class=\"fig-list\">\n<li>Der Container <code>EcuMDefaultShutdownTarget</code> muss genau einmal instanziiert werden (Multiplizität 1..1).</li>\n<li>Der Enumerationsparameter heißt identisch zum Container <code>EcuMDefaultShutdownTarget</code> und besitzt die Literale <code>EcuMShutdownTargetSleep</code>, <code>EcuMShutdownTargetOff</code> und <code>EcuMShutdownTargetReset</code>.</li>\n<li>Die Anzahl konfigurierbarer Ziel-Schlafmodi (<code>EcuMSleepMode</code>) sowie Ziel-Resetmodi (<code>EcuMResetMode</code>) ist normativ auf maximal 256 Einträge beschränkt (Multiplizität 1..256).</li>\n<li>Wird als Herunterfahrziel Sleep oder Reset gewählt, kann die optionale symbolische Referenz (<code>0..1</code>) auf eine der maximal 256 Modusdefinitionen gesetzt werden. Für Off ist keine Modusreferenz vorgesehen.</li>\n</ul>"}], "trans": [{"from": "FIG-c284d7b029c47722", "to": "FIG-68aaa5d915b806e7", "fr": "R4.0.3", "tr": "R4.1.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Diagramm-Neu-Rendering / Skalierung ohne inhaltliche Modelländerungen (identische Container, Parameter, Literale, Referenzen und Multiplizitäten).</li>\n</ul>"}, {"from": "FIG-68aaa5d915b806e7", "to": "FIG-e47f70a8847c89f8", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-e47f70a8847c89f8", "to": "FIG-20a9044bd53ef151", "fr": "R4.2.2", "tr": "R4.3.1", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Parametername geändert: <code>EcuMDefaultState</code> zu <code>EcuMDefaultShutdownTarget</code>.</li>\n<li>Enumeration-Literale umbenannt: <code>EcuMStateSleep</code>, <code>EcuMStateOff</code> und <code>EcuMStateReset</code> zu <code>EcuMShutdownTargetSleep</code>, <code>EcuMShutdownTargetOff</code> und <code>EcuMShutdownTargetReset</code>.</li>\n<li>Obere Kardinalität (<code>upperMultiplicity</code>) der Zielcontainer <code>EcuMSleepMode</code> und <code>EcuMResetMode</code>: von unbeschränkt (<code>*</code>) auf <code>256</code> beschränkt.</li>\n</ul>"}]};
